698	 * One pass per scheduler tick. Each org is only processed during the UTC hour
699	 * it configured, so a tick that runs every few minutes still sends exactly one
700	 * digest per day per recipient.
701	 */
702	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
703	  return runJob("digest-email", async (result) => {
704	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
705	
706	    for (const orgId of orgIds) {
707	      const org = await orgRepo.findOrgById(orgId);
708	      if (!org || !shouldRunForOrg(org, now)) continue;
709	
710	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
711	
712	      const windowEnd = toIsoTimestamp(now);
713	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
714	
715	      for (const recipientId of await listDigestRecipients(orgId)) {
716	        try {
717	          const bundle = await buildDigest(
718	            orgId,
719	            recipientId,
720	            windowStart,
721	            windowEnd,
722	          );
723	          if (!bundle) continue;
724	
725	          const recipient = await userRepo.findUserById(recipientId);
726	          if (!recipient) continue;
727	
728	          const rendered = await renderDigest(bundle, recipient);
729	          await sendEmail({ to: recipient.email, ...rendered });
730	
