738	          result.processed += 1;
739	        } catch (error) {
740	          result.failed += 1;
741	          logger.error("digest failed", {
742	            orgId,
743	            recipientId,
744	            reason: error instanceof Error ? error.message : String(error),
745	          });
746	        }
747	      }
748	    }
749	  });
750	}
