922	 */
923	export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
924	  const now = new Date().toISOString();
925	  const due = pending
926	    .filter((job) => job.runAt <= now)
927	    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
928	    .slice(0, Math.max(0, limit));
929	
930	  let completed = 0;
931	
932	  for (const job of due) {
933	    remove(job.id);
934	
935	    try {
936	      await runHandler(job);
937	      completed += 1;
938	    } catch (error) {
939	      const attempts = job.attempts + 1;
940	
941	      if (attempts >= MAX_ATTEMPTS) {
942	        logger.error("job dropped after max attempts", {
943	          id: job.id,
944	          kind: job.kind,
945	          attempts,
946	        });
947	        continue;
948	      }
