/**
 * Workspace deletion as a grace period followed by a purge: a deleted
 * organization is kept inert for `DELETED_WORKSPACE_RETENTION_DAYS`, its owner
 * can restore it inside that window, and the retention sweep removes every
 * trace of it afterwards.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityEvents, getDb, issues, members, organizations, users } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  resolveOrgBySlug,
  restoreOrganization,
} from "@/server/services/organization-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let counter = 0;

async function freshTenant(): Promise<Tenant> {
  counter += 1;
  const tenant = await createTenant(`lifecycle-${counter}`);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function remove(tenant: Tenant) {
  return deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

function deletedAt(orgId: OrgId): number {
  const row = getDb().select().from(organizations).where(eq(organizations.id, orgId)).get();
  return Date.parse(row?.archivedAt ?? "");
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and records it in the audit log", async () => {
    const tenant = await freshTenant();
    detachers.push(registerActivityListeners());
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.deleted", (payload) => void seen.push(payload)));

    await remove(tenant);

    expect(seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);

    const rows = getDb()
      .select()
      .from(activityEvents)
      .where(eq(activityEvents.orgId, tenant.org.id))
      .all();
    expect(rows).toEqual([
      expect.objectContaining({
        action: "organization.deleted",
        subjectKind: "organization",
        subjectId: tenant.org.id,
        actorId: tenant.userIds.owner,
      }),
    ]);
  });

  it("refuses to delete a workspace twice", async () => {
    const tenant = await freshTenant();
    await remove(tenant);
    await expect(remove(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("hides the workspace, keeps its slug reserved and leaves it inert", async () => {
    const tenant = await freshTenant();
    const token = "lifecycle-invite-token";
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@lifecycle.test", role: "member", expiresInDays: 7 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const before = await usageRepo.getUsage(tenant.org.id);

    await remove(tenant);

    await expect(resolveOrgBySlug(tenant.org.slug)).resolves.toBeNull();
    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toEqual([]);
    await expect(orgRepo.listTakenOrgSlugs(tenant.org.slug)).resolves.toContain(tenant.org.slug);

    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
        title: "t",
        body: "b",
        href: "/",
        actorId: null,
      }),
    ).resolves.toEqual([]);

    await expect(
      acceptInvitation(tenant.userIds.owner, { token }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(invitationRepo.listPendingInvitations(tenant.org.id)).resolves.toHaveLength(1);

    await runUsageRollupJob(new Date());
    await runCleanupArchivedJob(new Date());
    await expect(usageRepo.getUsage(tenant.org.id)).resolves.toEqual(before);
    await expect(usageRepo.listOrgIdsForRollup(1000)).resolves.not.toContain(tenant.org.id);
  });
});

describe("restoring a workspace", () => {
  it("brings it back for its owner and publishes organization.restored", async () => {
    const tenant = await freshTenant();
    await remove(tenant);
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.restored", (payload) => void seen.push(payload)));

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(restored.archivedAt).toBeNull();
    expect(seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.owner,
        slug: tenant.org.slug,
      }),
    ]);
    await expect(resolveOrgBySlug(tenant.org.slug)).resolves.not.toBeNull();
    await expect(usageRepo.listOrgIdsForRollup(1000)).resolves.toContain(tenant.org.id);
  });

  it("is owner-only, and unknown to strangers", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    await remove(tenant);

    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      restoreOrganization(other.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.owner, "01HZZZNOSUCHORGXXXXXXXXXXX" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await freshTenant();
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.restored", (payload) => void seen.push(payload)));

    const same = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(same).toEqual(tenant.org);
    expect(seen).toEqual([]);
  });

  it("is refused from the instant the window closes, purged or not", async () => {
    const tenant = await freshTenant();
    await remove(tenant);
    const at = deletedAt(tenant.org.id);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(at + WINDOW_MS));
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    vi.setSystemTime(new Date(at + WINDOW_MS - 1));
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).resolves.toMatchObject({ archivedAt: null });
  });
});

describe("the purge", () => {
  it("leaves live and recently deleted workspaces alone", async () => {
    const live = await freshTenant();
    const recent = await freshTenant();
    await remove(recent);
    const at = deletedAt(recent.org.id);

    await runCleanupArchivedJob(new Date(at + WINDOW_MS - 1));

    await expect(orgRepo.findOrgById(live.org.id)).resolves.not.toBeNull();
    await expect(orgRepo.findOrgById(recent.org.id)).resolves.not.toBeNull();
    expect(
      getDb().select().from(members).where(eq(members.orgId, recent.org.id)).all(),
    ).toHaveLength(4);
  });

  it("removes every trace of an expired workspace but keeps the users", async () => {
    const tenant = await freshTenant();
    const bystander = await freshTenant();
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Doomed" }),
    );
    await remove(tenant);
    const at = deletedAt(tenant.org.id);

    await runCleanupArchivedJob(new Date(at + WINDOW_MS));

    const db = getDb();
    const tables = db.$client
      .prepare(
        "SELECT m.name AS name FROM sqlite_master m JOIN pragma_table_info(m.name) c ON c.name = 'org_id' WHERE m.type = 'table'",
      )
      .all() as readonly { name: string }[];
    expect(tables.length).toBeGreaterThan(10);
    for (const { name } of tables) {
      const left = db.$client
        .prepare(`SELECT count(*) AS n FROM "${name}" WHERE org_id = ?`)
        .get(tenant.org.id) as { n: number };
      expect(left.n, name).toBe(0);
    }

    await expect(orgRepo.findOrgById(tenant.org.id)).resolves.toBeNull();
    expect(db.select().from(users).where(eq(users.id, tenant.userIds.owner)).all()).toHaveLength(1);
    expect(db.select().from(issues).where(eq(issues.orgId, bystander.org.id)).all()).toEqual([]);
    await expect(orgRepo.findOrgById(bystander.org.id)).resolves.not.toBeNull();
    expect(
      db.select().from(members).where(eq(members.orgId, bystander.org.id)).all(),
    ).toHaveLength(4);

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await createOrganization(tenant.userIds.owner, {
      name: "Reborn",
      slug: tenant.org.slug,
      plan: "free",
    });
    expect(reborn.slug).toBe(tenant.org.slug);
  });
});

